:root {
  /* Canvas & Surface Planes */
  --surface-ground: #101010; /* Primary Canvas Ground (45%) */
  --surface-elevated: #303040; /* Elevated Card & Module Surface */
  --surface-glass: rgba(255, 255, 255, 0.04); /* Translucent Overlay Card */

  /* Typography & Ink Hierarchy */
  --ink-primary: #A0B0C0; /* Display Headlines & Primary Numerals */
  --ink-secondary: #D0D0C0; /* Body Copy, Kickers & Navigation Links */
  --ink-on-accent: #FFFFFF; /* High-Contrast CTA Button Label */

  /* Interactive Accents & Signals */
  --accent-primary: #402010; /* Primary CTA Button & Active Indicator */
  --accent-hover: #402010E6; /* Hover State Fill (90% Opacity / Brightened) */

  /* Structural Borders & Grid Hairlines */
  --border-hairline: #504030; /* 1px Card & Section Divider Rule */
  --border-grid-guide: rgba(255, 255, 255, 0.06); /* Vertical Column Guide Line */

  /* Layout & Radius Tokens */
  --radius-pill: 9999px;
  --radius-card: 10px;
  --radius-media: 6px;
  --container-max: 1280px;
}

:root {
